package com.jinloes.practice;
public class Solution { public static class TreeNode { public int value; public TreeNode left; public TreeNode right; public TreeNode(int value){this.value=value;} public TreeNode(int value,TreeNode left,TreeNode right){this.value=value;this.left=left;this.right=right;} } public static TreeNode buildBalanced(int[] values){ TreeNode root=null; for(int i=values.length-1;i>=0;i--) root=new TreeNode(values[i],null,root); return root; } }
